static RK_CHAR optstr[] = "?::w:h:d:c:m:l:f:t:W:L:M:v:V:s:C:";
static void print_usage(const RK_CHAR *name) {
	printf("usage example:\n");
	printf("\t%s -w 3840 -h 2160 -d 0 -c 0 -m 1 -l 50 -t 1 -f /data/rkeis_config.json -M 1\n", name);
	printf("\t-w: VI width, Default:3840\n");
	printf("\t-h: VI height, Default:2160\n");
	printf("\t-d: dev id, Default:0\n");
	printf("\t-c: chn id, Default:0\n");
	printf("\t-m: mode, Default:1\n");
    printf("\t-l: frame count, Default:50\n");
    printf("\t-t: attach mode, Default:1\n");
    printf("\t-f: gdc eis file, Default:NULL\n");
    printf("\t-t: gdc mode, Default:1(0:eis, 1:fec)\n");
    printf("\t-L: loop count, Default:1\n");
    printf("\t-s: mesh, Default:/data/rkalg_idc_gpu_meshxy_step16x8.bin\n");
}
#endif

int main(int argc, char *argv[]) {
#if defined(RV1126B) || defined(RK3572)
    RK_S32 s32Ret = RK_FAILURE;
    RK_CHAR strBuff[128] = {0};
    FILE *imuFp = NULL;
    FILE *viFp = NULL;
    int c = 0;
    TEST_VI_CTX_S *ctx = (TEST_VI_CTX_S *)(malloc(sizeof(TEST_VI_CTX_S)));
    memset(ctx, 0, sizeof(TEST_VI_CTX_S));

    RK_S32 s32TestCount = 0;
    RK_S32 s32TestFinishQuit = 1;
    ctx->width = 3840;
    ctx->height = 2160;
    ctx->devId = 0;
    ctx->pipeId = ctx->devId;
    ctx->channelId = 0;
    ctx->loopCountSet = 50;
    ctx->enMode = TEST_VI_MODE_BIND_GDC_BIND_VO;
    ctx->stChnAttr.stIspOpt.u32BufCount = 3;
    ctx->s32MemType = VI_V4L2_MEMORY_TYPE_DMABUF;
    ctx->stChnAttr.stIspOpt.enCaptureType = VI_V4L2_CAPTURE_TYPE_VIDEO_CAPTURE;
    ctx->stChnAttr.u32Depth = 0;
    ctx->aEntityName = RK_NULL;
    ctx->stChnAttr.enPixelFormat = RK_FMT_YUV420SP;
    ctx->stChnAttr.stFrameRate.s32SrcFrameRate = -1;
    ctx->stChnAttr.stFrameRate.s32DstFrameRate = -1;
    ctx->bEnSwcac = RK_FALSE;
    ctx->bGetStream = RK_TRUE;
    ctx->bAttachFrmInfo = RK_TRUE;
    ctx->modTestCnt = 1;
    ctx->maxWidth = 0;
    ctx->maxHeight = 0;
    ctx->bSaveVlogPath = NULL;
    ctx->s32HdrMode = 0;
    ctx->bIfDevBindPipe = RK_TRUE;
    ctx->s32MemMode = 1;
    ctx->bGdcMode = 1;
    RK_LOGE("test running enter!");

	while ((c = getopt(argc, argv, optstr)) != -1) {
        switch (c) {
        case 'w':
            ctx->width = atoi(optarg);
            break;
        case 'h':
            ctx->height = atoi(optarg);
            break;
        case 'd':
            ctx->devId = atoi(optarg);
            break;
        case 'c':
            ctx->channelId = atoi(optarg);
            break;
        case 'm':
            ctx->enMode = atoi(optarg);
            break;
        case 'l':
            ctx->loopCountSet = atoi(optarg);
            break;
        case 'f':
            ctx->pGdcCfgFile = optarg;
            break;
        case 't':
            ctx->bAttachFrmInfo = atoi(optarg);
            break;
        case 'W':
            ctx->bGdcWriteFlag = atoi(optarg);
            break;
        case 'L':
            ctx->modTestCnt = atoi(optarg);
            break;
        case 'M':
            ctx->bGdcMode = atoi(optarg);
            break;
        case 'v':
            ctx->stChnAttr.enVideoFormat = atoi(optarg);
            break;
        case 'V':
            ctx->s32GdcVFormat = atoi(optarg);
            break;
        case 'C':
            ctx->s32GdcCompMode = atoi(optarg);
            break;
        case 's':
            ctx->pGdcMesh = optarg;
            break;
        case '?':
        default:
            print_usage(argv[0]);
            return -1;
        }
	}

	printf("#width: %d\n", ctx->width);
	printf("#height: %d\n", ctx->height);
	printf("#enMode: %d\n", ctx->enMode);
	printf("#bGdcMode: %d\n", ctx->bGdcMode);
	printf("#loopCountSet: %d\n", ctx->loopCountSet);
	printf("#bGdcWriteFlag: %d\n", ctx->bGdcWriteFlag);
	printf("#modTestCnt: %d\n", ctx->modTestCnt);
	printf("#pGdcCfgFile: %s\n", ctx->pGdcCfgFile);
	printf("#vi video format: %d\n", ctx->stChnAttr.enVideoFormat);
	printf("#gdc video dst format: %d\n", ctx->s32GdcVFormat);
	printf("#gdc video dst compress mode: %d\n", ctx->s32GdcCompMode);
    printf("#pGdcMesh: %s\n", ctx->pGdcMesh);

    if (!ctx->width || !ctx->height) {
        printf("ctx->width(%d) or height(%d) = 0\n",
                ctx->width, ctx->height);
        goto __FAILED2;
    }

    if (ctx->pipeId != ctx->devId)
        ctx->pipeId = ctx->devId;

    if (ctx->pipeId != ctx->devId)
        ctx->pipeId = ctx->devId;

    ctx->stChnAttr.stIspOpt.enMemoryType = (VI_V4L2_MEMORY_TYPE)ctx->s32MemType;
    signal(SIGINT, sigterm_handler);

    imuFp = fopen("/tmp/imu_info.txt", "wb+");
    if (!imuFp) {
        printf("fopen imu file fail!\n");
        goto __FAILED;
    }

    for (int i = 0; i < 2000; i++) {
        fprintf(imuFp, "%.15lf %.15lf %.15lf %.15lf %.15lf %.15lf %.15lf %lld\n",
            imuInfo[8*i], imuInfo[8*i + 1], imuInfo[8*i + 2], imuInfo[8*i + 3],
            imuInfo[8*i + 4], imuInfo[8*i + 5], imuInfo[8*i + 6], (long long)imuInfo[8*i + 7]);
        fflush(imuFp);
    }

    fclose(imuFp);
    imuFp = NULL;

    viFp = fopen("/tmp/vi_info.txt", "wb+");
    if (!viFp) {
        printf("fopen vi_info file fail!\n");
        goto __FAILED;
    }

    for (int i = 0; i < 704; i++) {
        fprintf(viFp, "%lld %lld %lld %lld %lld %lld %.6lf\n",
            (long long)viInfo[i][0], (long long)viInfo[i][1],
            (long long)viInfo[i][2], (long long)viInfo[i][3],
            (long long)viInfo[i][4], (long long)viInfo[i][5], viInfo[i][6]);
        fflush(viFp);
    }

    fclose(viFp);
    viFp = NULL;
    if (setenv("rt_debug_eis_imu_delay", "625", 1) != 0) {
        printf("export delay failed\n");
        return -1;
    }

    if (setenv("rt_debug_eis_imu_file", "/tmp/imu_info.txt", 1) != 0) {
        printf("export imu info failed\n");
        return -1;
    }

    if (setenv("rt_debug_eis_vi_info_file", "/tmp/vi_info.txt", 1) != 0) {
        printf("export vi info failed\n");
        return -1;
    }

    system("export");
    if (!ctx->bGdcMode) {
        if (ctx->pGdcCfgFile == RK_NULL) {
            FILE* eisFp = fopen("/tmp/rkeis_config.json", "w");
            if (eisFp == NULL) {
                printf("fopen eis json failed\n");
                return -1;
            }


            int bytes_written = fwrite(json_content, sizeof(char), strlen(json_content), eisFp);
            if (bytes_written != strlen(json_content)) {
                printf("fwrite eis json failed\n");
                fclose(eisFp);
                return -1;
            }


            if (fclose(eisFp) != 0) {
                printf("fclose eis json failed\n");
                return -1;
            }

            ctx->pGdcCfgFile = "/tmp/rkeis_config.json";
        }
    } else if (ctx->bGdcMode == 2) {
        if (ctx->pGdcCfgFile == RK_NULL) {
            FILE* disFp = fopen("/tmp/rkdis_config.json", "w");
            if (disFp == NULL) {
                printf("fopen dis json failed\n");
                return -1;
            }


            int bytes_written = fwrite(dis_json_content, sizeof(char), strlen(dis_json_content), disFp);
            if (bytes_written != strlen(dis_json_content)) {
                printf("fwrite dis json failed\n");
                fclose(disFp);
                return -1;
            }


            if (fclose(disFp) != 0) {
                printf("fclose dis json failed\n");
                return -1;
            }

            ctx->pGdcCfgFile = "/tmp/rkdis_config.json";
        }
    }

    if (RK_MPI_SYS_Init() != RK_SUCCESS) {
        printf("rk mpi sys init fail!\n");
        goto __FAILED;
    }

    memset(&ctx->stModParam, 0, sizeof(ctx->stModParam));
    ctx->stModParam.enViModType = VI_DEV_PIPE_MODE;
    s32Ret = RK_MPI_VI_GetModParam(&ctx->stModParam);
    if (s32Ret)
        RK_LOGE("RK_MPI_VI_GetModParam fail:%#X", s32Ret);

    RK_LOGI("vi mod:%d  dev_pipe_mode:%d", ctx->stModParam.enViModType,
            ctx->stModParam.stDevPipeModParam.enDevPipeMode);

    do {
        switch (ctx->enMode) {
            case TEST_VI_MODE_BIND_GDC:
                s32Ret = test_vi_bind_gdc_loop(ctx);
            break;
            case TEST_VI_MODE_BIND_GDC_BIND_VO:
                s32Ret = test_vi_bind_gdc_bind_vo_loop(ctx);
            break;
            case TEST_VI_MODE_BIND_GDC_GET_BIND_VO:
                s32Ret = test_vi_bind_gdc_get_bind_vo_loop(ctx);
            break;
            default:
                RK_LOGE("no support such test mode:%d", ctx->enMode);
            break;
        }

        s32TestCount++;
        RK_LOGE("-------------------mode %d Test success Total: %d, Now Count:%d-------------------",
                ctx->enMode, ctx->modTestCnt, s32TestCount);
    } while (s32TestCount < ctx->modTestCnt);

    if (!s32TestFinishQuit) {
        while(bBlock) {
            sleep(1);
        }
    }
__FAILED:
    RK_LOGE("test running exit:%d", s32Ret);
    if (ctx->bSaveVlogPath) {
        memset(strBuff, 0, sizeof(strBuff));
        sprintf(strBuff, "dumpsys cat /dev/mpi/vlog > %s", ctx->bSaveVlogPath);
        system(strBuff);
        RK_LOGI("save vlog info to %s", ctx->bSaveVlogPath);
    }

    RK_MPI_SYS_Exit();
__FAILED2:
    if (ctx) {
        free(ctx);
        ctx = RK_NULL;
    }

    return 0;
#else
    RK_LOGE("GDC not compiled");
    return RK_FALSE;
#endif
}
